<?php
declare(strict_types=1);
namespace Architex\Http;
use Architex\Http\Controller\SurveyJobController;use Architex\Http\Middleware\PermissionMiddleware;
final readonly class SurveyJobRoutes{public function __construct(private SurveyJobController$c,private PermissionMiddleware$read,private PermissionMiddleware$write){}public function register(Router$r):void{$r->get('/api/v1/projects/{projectId}/survey-jobs',fn(Request$q):Response=>$this->read->process($q,$this->c->index(...)));$r->post('/api/v1/projects/{projectId}/survey-jobs',fn(Request$q):Response=>$this->write->process($q,$this->c->create(...)));$r->get('/api/v1/survey-jobs/{jobId}',fn(Request$q):Response=>$this->read->process($q,$this->c->show(...)));$r->post('/api/v1/survey-jobs/{jobId}/observations',fn(Request$q):Response=>$this->write->process($q,$this->c->observation(...)));$r->post('/api/v1/survey-jobs/{jobId}/deliverables',fn(Request$q):Response=>$this->write->process($q,$this->c->deliverable(...)));$r->post('/api/v1/survey-jobs/{jobId}/fees',fn(Request$q):Response=>$this->write->process($q,$this->c->fees(...)));$r->post('/api/v1/survey-jobs/{jobId}/issue',fn(Request$q):Response=>$this->write->process($q,$this->c->issue(...)));$r->get('/api/v1/survey-jobs/{jobId}/exports/{format}',fn(Request$q):Response=>$this->read->process($q,$this->c->export(...)));}}
